def regex_match(s: str, p: str) -> bool:
    memo = {}
    def dp(si, pi):
        if (si, pi) in memo:
            return memo[(si, pi)]
        if pi == len(p):
            res = si == len(s)
            memo[(si, pi)] = res
            return res

        first_match = si < len(s) and (p[pi] == s[si] or p[pi] == '.')

        if pi + 1 < len(p) and p[pi+1] == '*':
            res = dp(si, pi+2) or (first_match and dp(si+1, pi))
        elif pi + 1 < len(p) and p[pi+1] == '+':
            res = first_match and (dp(si+1, pi) or dp(si+1, pi+2))
        elif pi + 1 < len(p) and p[pi+1] == '?':
            res = dp(si, pi+2) or (first_match and dp(si+1, pi+2))
        else:
            res = first_match and dp(si+1, pi+2)

        memo[(si, pi)] = res
        return res

    return dp(0, 0)
