def calc(expr: str) -> float:
    # Tokenizer
    tokens = []
    i = 0
    n = len(expr)
    while i < n:
        c = expr[i]
        if c.isspace():
            i += 1
            continue

        if c.isdigit() or c == '.':
            j = i
            has_digit = False
            has_dot = False
            while j < n:
                ch = expr[j]
                if ch.isdigit():
                    has_digit = True
                    j += 1
                elif ch == '.':
                    if has_dot:
                        break
                    has_dot = True
                    j += 1
                else:
                    break

            if j > i:
                num_str = expr[i:j]
                tokens.append(('NUMBER', float(num_str)))
                i = j
            else:
                i += 1
        elif c == '*':
            if i + 1 < n and expr[i+1] == '*':
                tokens.append(('POW', '**'))
                i += 2
            else:
                tokens.append(('STAR', '*'))
                i += 1
        elif c == '/':
            tokens.append(('SLASH', '/'))
            i += 1
        elif c == '+':
            tokens.append(('PLUS', '+'))
            i += 1
        elif c == '-':
            tokens.append(('MINUS', '-'))
            i += 1
        elif c == '(':
            tokens.append(('LPAREN', '('))
            i += 1
        elif c == ')':
            tokens.append(('RPAREN', ')'))
            i += 1
        else:
            raise ValueError(f"Unexpected character: {c}")

    tokens.append(('EOF', None))

    # Parser
    pos = 0

    def peek():
        return tokens[pos]

    def consume():
        nonlocal pos
        tok = tokens[pos]
        pos += 1
        return tok

    def expect(type_):
        tok = peek()
        if tok[0] != type_:
            raise ValueError(f"Expected {type_}, got {tok}")
        return consume()

    def parse_expr():
        # expr -> term { ('+' | '-') term }
        left = parse_term()
        while True:
            tok = peek()
            if tok[0] in ('PLUS', 'MINUS'):
                op = consume()[1]
                right = parse_term()
                if op == '+':
                    left += right
                else:
                    left -= right
            else:
                break
        return left

    def parse_term():
        # term -> factor { ('*' | '/') factor }
        left = parse_factor()
        while True:
            tok = peek()
            if tok[0] in ('STAR', 'SLASH'):
                op = consume()[1]
                right = parse_factor()
                if op == '*':
                    left *= right
                else:
                    left /= right
            else:
                break
        return left

    def parse_factor():
        # factor -> ('+' | '-') factor | power
        tok = peek()
        if tok[0] in ('PLUS', 'MINUS'):
            op = consume()[1]
            val = parse_factor()
            if op == '-':
                return -val
            else:
                return val
        return parse_power()

    def parse_power():
        # power -> atom { '**' factor }  (Right associative)
        # Note: parse_factor calls parse_power, so the RHS of ** is parsed
        # recursively, ensuring right associativity.
        base = parse_atom()
        while True:
            tok = peek()
            if tok[0] == 'POW':
                consume()
                rhs = parse_factor()
                base = base ** rhs
            else:
                break
        return base

    def parse_atom():
        # atom -> NUMBER | '(' expr ')'
        tok = peek()
        if tok[0] == 'NUMBER':
            return consume()[1]
        elif tok[0] == 'LPAREN':
            consume()
            val = parse_expr()
            expect('RPAREN')
            return val
        else:
            raise ValueError(f"Unexpected token: {tok}")

    result = parse_expr()
    if peek()[0] != 'EOF':
        raise ValueError("Unexpected tokens after expression")
    return result
