def count_n_queens(n: int) -> int:
    def backtrack(row, cols, ld, rd):
        if row == n:
            return 1
        count = 0
        available = ((1 << n) - 1) & ~(cols | ld | rd)
        while available:
            pos = available & -available
            count += backtrack(row + 1, cols | pos, (ld | pos) << 1, (rd | pos) >> 1)
            available &= available - 1
        return count
    return backtrack(0, 0, 0, 0)
