import heapq
from collections import defaultdict

def median_sliding_window(nums: list[int], k: int) -> list[float]:
    lo = []  # max-heap (stores negated values)
    hi = []  # min-heap
    delayed = defaultdict(int)
    balance = 0

    def prune():
        while lo and delayed.get(-lo[0], 0) > 0:
            delayed[-lo[0]] -= 1
            heapq.heappop(lo)
        while hi and delayed.get(hi[0], 0) > 0:
            delayed[hi[0]] -= 1
            heapq.heappop(hi)

    def add(num):
        nonlocal balance
        if not lo or num <= -lo[0]:
            heapq.heappush(lo, -num)
            balance += 1
        else:
            heapq.heappush(hi, num)
            balance -= 1
        prune()
        rebalance()

    def remove(num):
        nonlocal balance
        if num <= -lo[0]:
            delayed[-num] += 1
            balance -= 1
        else:
            delayed[num] += 1
            balance += 1
        prune()
        rebalance()

    def rebalance():
        nonlocal balance
        if balance > 1:
            heapq.heappush(hi, -heapq.heappop(lo))
            balance -= 2
        elif balance < 0:
            heapq.heappush(lo, -heapq.heappop(hi))
            balance += 2

    for i in range(k):
        add(nums[i])

    res = []
    for i in range(len(nums) - k + 1):
        if i > 0:
            remove(nums[i - 1])
            add(nums[i + k - 1])
        if k % 2 == 1:
            res.append(float(-lo[0]))
        else:
            res.append((-lo[0] + hi[0]) / 2.0)

    return res
