import datetime

def business_days(start: str, end: str, holidays: list[str]) -> int:
    # Parse start and end dates
    try:
        d_start = datetime.date.fromisoformat(start)
        d_end = datetime.date.fromisoformat(end)
    except ValueError:
        return 0

    # Handle direction: if end < start, return negative of business_days(end, start, holidays)
    if d_start > d_end:
        d_start, d_end = d_end, d_start
        sign = -1
    else:
        sign = 1

    # Calculate total weekdays in [d_start, d_end)
    start_ord = d_start.toordinal()
    end_ord = d_end.toordinal()
    diff = end_ord - start_ord

    if diff <= 0:
        return 0

    # Full weeks contribution (5 weekdays per week)
    total = (diff // 7) * 5

    # Remainder days contribution
    rem = diff % 7
    start_wd = d_start.weekday() # 0=Monday, 6=Sunday

    # Check each day in the remainder
    for i in range(rem):
        if (start_wd + i) % 7 < 5:
            total += 1

    # Subtract holidays that are weekdays and within the range
    # Use a set to handle duplicates efficiently
    holiday_ordinals = set()
    for h_str in holidays:
        try:
            h_date = datetime.date.fromisoformat(h_str)
            # Check if it is a weekday and falls within [d_start, d_end)
            if h_date.weekday() < 5 and d_start <= h_date < d_end:
                holiday_ordinals.add(h_date.toordinal())
        except ValueError:
            pass # Skip invalid holiday strings

    return sign * (total - len(holiday_ordinals))
