def num_decodings(s: str) -> int:
    MOD = 1000000007
    n = len(s)

    # a stores DP[i-1], b stores DP[i]
    # Initially for i=0 (processing s[0]), we need DP[-1]=0 and DP[0]=1
    a = 0
    b = 1

    for i in range(n):
        c = s[i]

        # w1: ways to decode c as a single digit
        if c == '0':
            w1 = 0
        elif c == '*':
            w1 = 9
        else:
            w1 = 1

        # w2: ways to decode s[i-1]c as a two-digit number
        w2 = 0
        if i > 0:
            p = s[i-1]
            if p == '*':
                if c == '*':
                    w2 = 15
                else:
                    # p='*', c is digit
                    # 10*1 + c <= 26 (always true for c<=9)
                    # 10*2 + c <= 26 <=> c <= 6
                    # 10*3 + c > 26
                    if c <= '6':
                        w2 = 2
                    else:
                        w2 = 1
            else:
                # p is digit
                if c == '*':
                    # p is digit, c is '*' (1-9)
                    if p == '1':
                        w2 = 9
                    elif p == '2':
                        w2 = 6
                    else:
                        w2 = 0
                else:
                    # p digit, c digit
                    if p == '1':
                        w2 = 1
                    elif p == '2':
                        if c <= '6':
                            w2 = 1
                        else:
                            w2 = 0
                    else:
                        w2 = 0

        # DP transition: DP[i+1] = w1 * DP[i] + w2 * DP[i-1]
        # Current b is DP[i], a is DP[i-1]
        # Update a to old b, b to new DP[i+1]
        # Tuple unpacking ensures RHS is evaluated with old values
        a, b = b, (w1 * b + w2 * a) % MOD

    return b
