import heapq
from collections import defaultdict

def alien_order(words: list[str]) -> str:
    adj = defaultdict(set)
    in_degree = {}
    chars = set()

    # Collect all unique characters
    for word in words:
        for char in word:
            chars.add(char)

    # Initialize in-degrees
    for char in chars:
        in_degree[char] = 0

    # Build graph
    for i in range(len(words) - 1):
        w1 = words[i]
        w2 = words[i+1]

        # Check for invalid prefix case: w2 is a prefix of w1
        # This happens if w1 is longer than w2 and w1 starts with w2.
        # Example: ["abc", "ab"] -> invalid because "ab" should come before "abc".
        if len(w1) > len(w2) and w1.startswith(w2):
            return ""

        # Find first difference to determine character order
        limit = min(len(w1), len(w2))
        for j in range(limit):
            if w1[j] != w2[j]:
                u = w1[j]
                v = w2[j]
                # Add edge u -> v if not already present
                if v not in adj[u]:
                    adj[u].add(v)
                    in_degree[v] += 1
                break # Only the first difference matters

    # Topological sort using a Min-Heap to get lexicographically smallest result
    pq = []
    for char in chars:
        if in_degree[char] == 0:
            heapq.heappush(pq, char)

    res = []
    while pq:
        u = heapq.heappop(pq)
        res.append(u)

        for v in adj[u]:
            in_degree[v] -= 1
            if in_degree[v] == 0:
                heapq.heappush(pq, v)

    # If result length is less than unique chars, there is a cycle
    if len(res) != len(chars):
        return ""

    return "".join(res)
