def kth_smallest_distance(nums: list[int], k: int) -> int:
    nums = sorted(nums)
    n = len(nums)
    if n < 2:
        return 0

    low = 0
    high = nums[-1] - nums[0]

    while low < high:
        mid = (low + high) // 2
        count = 0
        left = 0
        for right in range(n):
            target = nums[right] - mid
            while nums[left] < target:
                left += 1
            count += right - left

        if count >= k:
            high = mid
        else:
            low = mid + 1

    return low
