            elif word == 'not':
                tokens.append(('NOT', 'not'))
            elif word == 'and':
                tokens.append(('AND', 'and'))
            elif word == 'or':
                tokens.append(('OR', 'or'))
            else:
                tokens.append(('ID', word))
            i = j
        else:
            raise ValueError(f"Invalid character '{c}'")

