        while peek()[0] == 'OR':
            consume()
            right = parse_and()
            left = left or right
        return left

    def parse_and():
        left = parse_not()
        while peek()[0] == 'AND':
            consume()
            right = parse_not()
            left = left and right
        return left

    def parse_not():
