        if tok[0] == 'LPAREN':
            consume()
            val = parse_or()
            if peek()[0] != 'RPAREN':
                raise SyntaxError("Expected ')'")
            consume()
            return val
        elif tok[0] == 'TRUE':
            consume()
            return True
        elif tok[0] == 'FALSE':
            consume()
            return False
        elif tok[0] == 'ID':
            consume()
            name = tok[1]
            if name not in env:
                raise KeyError(name)
            return env[name]
        else:
            raise SyntaxError(f"Unexpected token: {tok}")

    result = parse_or()

    if peek()[0] != 'EOF':
        raise SyntaxError("Unexpected tokens at end of expression")

