def parse_json(text: str) -> object:
    """Parse a JSON document into Python objects."""

    class Parser:
        def __init__(self, text: str):
            self.text = text
            self.pos = 0

        def peek(self) -> str:
            if self.pos < len(self.text):
                return self.text[self.pos]
            return None

        def advance(self) -> str:
            ch = self.text[self.pos]
            self.pos += 1
            return ch

        def skip_whitespace(self):
            while self.pos < len(self.text) and self.text[self.pos] in ' \t\n\r':
                self.pos += 1

        def expect(self, expected: str):
            if self.pos >= len(self.text):
                raise ValueError(f"Unexpected end of input, expected '{expected}'")
            ch = self.text[self.pos]
            if ch != expected:
                raise ValueError(f"Expected '{expected}', got '{ch}' at position {self.pos}")
            self.pos += 1

        def parse(self) -> object:
            self.skip_whitespace()
            if self.pos >= len(self.text):
                raise ValueError("Empty input")

            result = self.parse_value()

            # After parsing, there should be no more non-whitespace characters
            self.skip_whitespace()
            if self.pos < len(self.text):
                raise ValueError(f"Trailing characters after JSON value at position {self.pos}")

            return result

        def parse_value(self) -> object:
            self.skip_whitespace()
            if self.pos >= len(self.text):
                raise ValueError("Unexpected end of input")

            ch = self.peek()

            if ch == '"':
                return self.parse_string()
            elif ch == '{':
                return self.parse_object()
            elif ch == '[':
                return self.parse_array()
            elif ch == 't':
                return self.parse_true()
            elif ch == 'f':
                return self.parse_false()
            elif ch == 'n':
                return self.parse_null()
            elif ch == '-' or ch.isdigit():
                return self.parse_number()
            else:
                raise ValueError(f"Unexpected character '{ch}' at position {self.pos}")

        def parse_string(self) -> str:
            self.expect('"')
            chars = []
            while True:
                if self.pos >= len(self.text):
                    raise ValueError("Unterminated string")
                ch = self.advance()
                if ch == '"':
                    break
                elif ch == '\\':
                    if self.pos >= len(self.text):
                        raise ValueError("Unterminated escape sequence")
                    esc = self.advance()
                    if esc == '"':
                        chars.append('"')
                    elif esc == '\\':
                        chars.append('\\')
                    elif esc == '/':
                        chars.append('/')
                    elif esc == 'b':
                        chars.append('\b')
                    elif esc == 'f':
                        chars.append('\f')
                    elif esc == 'n':
                        chars.append('\n')
                    elif esc == 'r':
                        chars.append('\r')
                    elif esc == 't':
                        chars.append('\t')
                    elif esc == 'u':
                        hex_str = ''
                        for _ in range(4):
                            if self.pos >= len(self.text):
                                raise ValueError("Incomplete unicode escape")
                            h = self.advance()
                            if h not in '0123456789abcdefABCDEF':
                                raise ValueError(f"Invalid hex digit '{h}' in unicode escape")
                            hex_str += h
                        code_point = int(hex_str, 16)
                        chars.append(chr(code_point))
                    else:
                        raise ValueError(f"Invalid escape character '\\{esc}'")
                else:
                    # Control characters are not allowed in strings
                    if ord(ch) < 0x20:
                        raise ValueError(f"Unescaped control character in string at position {self.pos - 1}")
                    chars.append(ch)
            return ''.join(chars)

        def parse_number(self) -> object:
            start_pos = self.pos

            # Check for negative sign
            if self.peek() == '-':
                self.advance()

            # Parse integer part
            if self.pos >= len(self.text):
                raise ValueError("Unexpected end of input in number")

            if self.peek() == '0':
                self.advance()
                # After leading zero, next char must not be a digit (no leading zeros like 01)
                if self.pos < len(self.text) and self.text[self.pos].isdigit():
                    raise ValueError(f"Leading zeros not allowed in numbers at position {start_pos}")
            elif self.peek() and self.text[self.pos].isdigit():
                while self.pos < len(self.text) and self.text[self.pos].isdigit():
                    self.advance()
            else:
                raise ValueError(f"Invalid number at position {start_pos}")

            is_float = False

            # Fractional part
            if self.pos < len(self.text) and self.text[self.pos] == '.':
                is_float = True
                self.advance()
                if self.pos >= len(self.text) or not self.text[self.pos].isdigit():
                    raise ValueError(f"Invalid number: expected digit after decimal point at position {self.pos}")
                while self.pos < len(self.text) and self.text[self.pos].isdigit():
                    self.advance()

            # Exponent part
            if self.pos < len(self.text) and self.text[self.pos] in 'eE':
                is_float = True
                self.advance()
                if self.pos < len(self.text) and self.text[self.pos] in '+-':
                    self.advance()
                if self.pos >= len(self.text) or not self.text[self.pos].isdigit():
                    raise ValueError(f"Invalid number: expected digit in exponent at position {self.pos}")
                while self.pos < len(self.text) and self.text[self.pos].isdigit():
                    self.advance()

            num_str = self.text[start_pos:self.pos]
            if is_float:
                return float(num_str)
            else:
                return int(num_str)

        def parse_object(self) -> dict:
            self.expect('{')
            obj = {}
            self.skip_whitespace()

            if self.peek() == '}':
                self.advance()
                return obj

            while True:
                self.skip_whitespace()
                if self.pos >= len(self.text):
                    raise ValueError("Unterminated object")

                if self.peek() != '"':
                    raise ValueError(f"Expected string key in object, got '{self.peek()}' at position {self.pos}")

                key = self.parse_string()

                self.skip_whitespace()
                self.expect(':')

                value = self.parse_value()
                obj[key] = value

                self.skip_whitespace()
                if self.pos >= len(self.text):
                    raise ValueError("Unterminated object")

                ch = self.peek()
                if ch == '}':
                    self.advance()
                    return obj
                elif ch == ',':
                    self.advance()
                    # Check for trailing comma
                    self.skip_whitespace()
                    if self.pos >= len(self.text):
                        raise ValueError("Trailing comma in object")
                    if self.peek() == '}':
                        raise ValueError("Trailing comma in object")
                else:
                    raise ValueError(f"Expected ',' or '}}' in object, got '{ch}' at position {self.pos}")

        def parse_array(self) -> list:
            self.expect('[')
            arr = []
            self.skip_whitespace()

            if self.peek() == ']':
                self.advance()
                return arr

            while True:
                self.skip_whitespace()
                if self.pos >= len(self.text):
                    raise ValueError("Unterminated array")

                value = self.parse_value()
                arr.append(value)

                self.skip_whitespace()
                if self.pos >= len(self.text):
                    raise ValueError("Unterminated array")

                ch = self.peek()
                if ch == ']':
                    self.advance()
                    return arr
                elif ch == ',':
                    self.advance()
                    # Check for trailing comma
                    self.skip_whitespace()
                    if self.pos >= len(self.text):
                        raise ValueError("Trailing comma in array")
                    if self.peek() == ']':
                        raise ValueError("Trailing comma in array")
                else:
                    raise ValueError(f"Expected ',' or ']' in array, got '{ch}' at position {self.pos}")

        def parse_true(self) -> bool:
            for expected_ch in 'true':
                if self.pos >= len(self.text):
                    raise ValueError("Unexpected end of input")
                if self.text[self.pos] != expected_ch:
                    raise ValueError(f"Invalid literal at position {self.pos}")
                self.pos += 1
            return True

        def parse_false(self) -> bool:
            for expected_ch in 'false':
                if self.pos >= len(self.text):
                    raise ValueError("Unexpected end of input")
                if self.text[self.pos] != expected_ch:
                    raise ValueError(f"Invalid literal at position {self.pos}")
                self.pos += 1
            return False

        def parse_null(self) -> None:
            for expected_ch in 'null':
                if self.pos >= len(self.text):
                    raise ValueError("Unexpected end of input")
                if self.text[self.pos] != expected_ch:
                    raise ValueError(f"Invalid literal at position {self.pos}")
                self.pos += 1
            return None

    parser = Parser(text)
    return parser.parse()
