        if p[j-1] in '*+?':
            prev_char = p[j-2]
            for i in range(m + 1):
                if p[j-1] == '*':
                    dp[i][j] = dp[i][j-2]
                    if i > 0 and dp[i-1][j] and matches(s[i-1], prev_char):
                        dp[i][j] = True
                elif p[j-1] == '+':
                    if i > 0 and matches(s[i-1], prev_char):
                        if dp[i-1][j] or dp[i-1][j-2]:
                            dp[i][j] = True
                elif p[j-1] == '?':
                    dp[i][j] = dp[i][j-2]
                    if i > 0 and dp[i-1][j-2] and matches(s[i-1], prev_char):
                        dp[i][j] = True
        else:
            for i in range(1, m + 1):
                if dp[i-1][j-1] and matches(s[i-1], p[j-1]):
                    dp[i][j] = True

    return dp[m][n]
