class Parser:
    def __init__(self, text):
        self.text = text
        self.pos = 0
        self.current_token = None
        self._advance()

    def _advance(self):
        # Skip whitespace
        while self.pos < len(self.text) and self.text[self.pos].isspace():
            self.pos += 1

        if self.pos >= len(self.text):
            self.current_token = ('EOF', None)
            return

        char = self.text[self.pos]

        if char.isdigit() or char == '.':
            start = self.pos
            has_dot = False
            while self.pos < len(self.text) and (self.text[self.pos].isdigit() or self.text[self.pos] == '.'):
                if self.text[self.pos] == '.':
                    if has_dot:
                        break
                    has_dot = True
                self.pos += 1

            num_str = self.text[start:self.pos]
            try:
                val = float(num_str)
            except ValueError:
                raise ValueError(f"Invalid number: {num_str}")
            self.current_token = ('NUMBER', val)

        elif char == '*':
            self.pos += 1
            if self.pos < len(self.text) and self.text[self.pos] == '*':
                self.pos += 1
                self.current_token = ('POW', None)
            else:
                self.current_token = ('STAR', None)
        elif char == '+':
            self.pos += 1
            self.current_token = ('PLUS', None)
        elif char == '-':
            self.pos += 1
            self.current_token = ('MINUS', None)
        elif char == '/':
            self.pos += 1
            self.current_token = ('SLASH', None)
        elif char == '(':
            self.pos += 1
            self.current_token = ('LPAREN', None)
        elif char == ')':
            self.pos += 1
            self.current_token = ('RPAREN', None)
        else:
            raise ValueError(f"Unexpected character: {char}")

    def eat(self, token_type):
        if self.current_token[0] == token_type:
            self._advance()
        else:
            raise ValueError(f"Expected {token_type}, got {self.current_token[0]}")

    def parse_expression(self):
        return self.parse_additive()

    def parse_additive(self):
        left = self.parse_multiplicative()
        while self.current_token[0] in ('PLUS', 'MINUS'):
            op = self.current_token[0]
            self._advance()
            right = self.parse_multiplicative()
            if op == 'PLUS':
                left += right
            else:
                left -= right
        return left

    def parse_multiplicative(self):
        left = self.parse_factor()
        while self.current_token[0] in ('STAR', 'SLASH'):
            op = self.current_token[0]
            self._advance()
            right = self.parse_factor()
            if op == 'STAR':
                left *= right
            else:
                left /= right
        return left

    def parse_factor(self):
        sign = 1
        while self.current_token[0] in ('PLUS', 'MINUS'):
            if self.current_token[0] == 'MINUS':
                sign *= -1
            self._advance()
        return sign * self.parse_power()

    def parse_power(self):
        base = self.parse_atom()
        if self.current_token[0] == 'POW':
            self._advance()
            exp = self.parse_factor()
            return base ** exp
        return base

    def parse_atom(self):
        if self.current_token[0] == 'NUMBER':
            val = self.current_token[1]
            self._advance()
            return val
        elif self.current_token[0] == 'LPAREN':
            self.eat('LPAREN')
            val = self.parse_expression()
            self.eat('RPAREN')
            return val
        else:
            raise ValueError(f"Unexpected token: {self.current_token[0]}")

def calc(expr: str) -> float:
    parser = Parser(expr)
    result = parser.parse_expression()
    if parser.current_token[0] != 'EOF':
        raise ValueError(f"Unexpected token after expression: {parser.current_token[0]}")
    return result
