def count_n_queens(n: int) -> int:
    def backtrack(row, cols, diag1, diag2):
        if row == n:
            return 1
        count = 0
        available = ~(cols | diag1 | diag2) & ((1 << n) - 1)
        while available:
            pos = available & -available
            available ^= pos
            count += backtrack(row + 1, cols | pos, (diag1 | pos) << 1, (diag2 | pos) >> 1)
        return count
    return backtrack(0, 0, 0, 0)
