def parse_json(text: str) -> object:
    class Parser:
        def __init__(self, s):
            self.s = s
            self.i = 0
            self.n = len(s)

        def peek(self):
            if self.i < self.n:
                return self.s[self.i]
            return None

        def advance(self):
            c = self.s[self.i]
            self.i += 1
            return c

        def expect(self, c):
            if self.peek() != c:
                raise ValueError(f"Expected '{c}'")
            self.advance()

        def skip_ws(self):
            while self.i < self.n and self.s[self.i] in ' \t\n\r':
                self.i += 1

        def parse(self):
            self.skip_ws()
            if self.i >= self.n:
                raise ValueError("Empty input")
            res = self.value()
            self.skip_ws()
            if self.i < self.n:
                raise ValueError("Trailing characters")
            return res

        def value(self):
            c = self.peek()
            if c == '"': return self.string()
            if c == '{': return self.object()
            if c == '[': return self.array()
            if c == 't': return self.literal(True, "true")
            if c == 'f': return self.literal(False, "false")
            if c == 'n': return self.literal(None, "null")
            if c == '-' or ('0' <= c <= '9'): return self.number()
            raise ValueError(f"Unexpected '{c}'")

        def literal(self, val, name):
            for ch in name:
                self.expect(ch)
            return val

        def string(self):
            self.expect('"')
            buf = []
            while True:
                if self.i >= self.n:
                    raise ValueError("Unterminated string")
                c = self.advance()
                if c == '"':
                    break
                if c == '\\':
                    if self.i >= self.n:
                        raise ValueError("Unterminated escape")
                    esc = self.advance()
                    if esc == '"': buf.append('"')
                    elif esc == '\\': buf.append('\\')
                    elif esc == '/': buf.append('/')
                    elif esc == 'b': buf.append('\b')
                    elif esc == 'f': buf.append('\f')
                    elif esc == 'n': buf.append('\n')
                    elif esc == 'r': buf.append('\r')
                    elif esc == 't': buf.append('\t')
                    elif esc == 'u':
                        hx = ""
                        for _ in range(4):
                            if self.i >= self.n: raise ValueError("Incomplete unicode")
                            d = self.advance()
                            if d not in '0123456789abcdefABCDEF':
                                raise ValueError("Bad hex")
                            hx += d
                        buf.append(chr(int(hx, 16)))
                    else:
                        raise ValueError(f"Bad escape \\{esc}")
                else:
                    if ord(c) < 0x20:
                        raise ValueError("Unescaped control char")
                    buf.append(c)
            return "".join(buf)

        def object(self):
            self.expect('{')
            d = {}
            self.skip_ws()
            if self.peek() == '}':
                self.advance()
                return d
            while True:
                if self.peek() != '"':
                    raise ValueError("Key must be string")
                k = self.string()
                self.skip_ws()
                self.expect(':')
                v = self.value()
                d[k] = v
                self.skip_ws()
                c = self.peek()
                if c == ',':
                    self.advance()
                    self.skip_ws()
                    if self.peek() == '}':
                        raise ValueError("Trailing comma")
                elif c == '}':
                    self.advance()
                    return d
                else:
                    raise ValueError("Expected , or }")

        def array(self):
            self.expect('[')
            l = []
            self.skip_ws()
            if self.peek() == ']':
                self.advance()
                return l
            while True:
                v = self.value()
                l.append(v)
                self.skip_ws()
                c = self.peek()
                if c == ',':
                    self.advance()
                    self.skip_ws()
                    if self.peek() == ']':
                        raise ValueError("Trailing comma")
                elif c == ']':
                    self.advance()
                    return l
                else:
                    raise ValueError("Expected , or ]")

        def number(self):
            start = self.i
            if self.peek() == '-':
                self.advance()

            if self.i >= self.n:
                raise ValueError("End of input in number")

            c = self.peek()
            if c == '0':
                self.advance()
                if self.i < self.n and '0' <= self.s[self.i] <= '9':
                    raise ValueError("Leading zero")
            elif '0' <= c <= '9':
                self.advance()
                while self.i < self.n and '0' <= self.s[self.i] <= '9':
                    self.advance()
            else:
                raise ValueError("Invalid number")

            is_float = False

            if self.i < self.n and self.s[self.i] == '.':
                is_float = True
                self.advance()
                if self.i >= self.n or not ('0' <= self.s[self.i] <= '9'):
                    raise ValueError("Missing fraction digits")
                while self.i < self.n and '0' <= self.s[self.i] <= '9':
                    self.advance()

            if self.i < self.n and self.s[self.i] in 'eE':
                is_float = True
                self.advance()
                if self.i < self.n and self.s[self.i] in '+-':
                    self.advance()
                if self.i >= self.n or not ('0' <= self.s[self.i] <= '9'):
                    raise ValueError("Missing exponent digits")
                while self.i < self.n and '0' <= self.s[self.i] <= '9':
                    self.advance()

            s_num = self.s[start:self.i]
            return float(s_num) if is_float else int(s_num)

    return Parser(text).parse()
