import math

def max_points(points: list[tuple[int, int]]) -> int:
    n = len(points)
    if n <= 2:
        return n

    max_count = 0

    for i in range(n):
        slopes = {}
        duplicates = 1
        xi, yi = points[i]

        for j in range(i + 1, n):
            xj, yj = points[j]
            dy = yj - yi
            dx = xj - xi

            if dy == 0 and dx == 0:
                duplicates += 1
                continue

            g = math.gcd(dy, dx)
            dy //= g
            dx //= g

            if dx < 0:
                dx = -dx
                dy = -dy
            elif dx == 0:
                dy = 1
            elif dy == 0:
                dx = 1

            slopes[(dy, dx)] = slopes.get((dy, dx), 0) + 1

        current_max = duplicates
        for count in slopes.values():
            if duplicates + count > current_max:
                current_max = duplicates + count

        if current_max > max_count:
            max_count = current_max

    return max_count
