def eval_bool(expr: str, env: dict[str, bool]) -> bool:
    tokens = []
    i = 0
    n = len(expr)
    while i < n:
        c = expr[i]
        if c.isspace():
            i += 1
        elif c == '(':
            tokens.append(('LPAREN', '('))
            i += 1
        elif c == ')':
            tokens.append(('RPAREN', ')'))
            i += 1
        elif c.isalpha() or c == '_':
            j = i
            while j < n and (expr[j].isalnum() or expr[j] == '_'):
                j += 1
            word = expr[i:j]
            if word == 'true':
                tokens.append(('LITERAL', 'true'))
            elif word == 'false':
                tokens.append(('LITERAL', 'false'))
            elif word == 'not':
                tokens.append(('OP', 'not'))
            elif word == 'and':
                tokens.append(('OP', 'and'))
            elif word == 'or':
                tokens.append(('OP', 'or'))
            else:
                tokens.append(('ID', word))
            i = j
        else:
            raise SyntaxError(f"Invalid character in expression: '{c}'")

    pos = 0

    def peek_type():
        if pos < len(tokens):
            return tokens[pos][0]
        return None

    def peek_val():
        if pos < len(tokens):
            return tokens[pos][1]
        return None

    def consume():
        nonlocal pos
        if pos < len(tokens):
            t = tokens[pos]
            pos += 1
            return t
        return None

    def parse_or():
        left = parse_and()
        while peek_type() == 'OP' and peek_val() == 'or':
            consume()
            right = parse_and()
            left = left or right
        return left

    def parse_and():
        left = parse_not()
        while peek_type() == 'OP' and peek_val() == 'and':
            consume()
            right = parse_not()
            left = left and right
        return left

    def parse_not():
        if peek_type() == 'OP' and peek_val() == 'not':
            consume()
            operand = parse_not()
            return not operand
        return parse_primary()

    def parse_primary():
        token = consume()
        if token is None:
            raise SyntaxError("Unexpected end of expression")

        type_, val = token

        if type_ == 'LITERAL':
            if val == 'true':
                return True
            elif val == 'false':
                return False
        elif type_ == 'LPAREN':
            val = parse_or()
            close = consume()
            if close is None or close[0] != 'RPAREN':
                raise SyntaxError(f"Expected ')', got '{close}'")
            return val
        elif type_ == 'ID':
            if val in env:
                return env[val]
            else:
                raise KeyError(val)
        else:
            raise SyntaxError(f"Unexpected token: {val}")

    result = parse_or()

    if pos < len(tokens):
        raise SyntaxError(f"Unexpected token after expression: {tokens[pos]}")

    return result
