def calc(expr: str) -> float:
    # Tokenizer
    def tokenize(s):
        tokens = []
        i = 0
        n = len(s)
        while i < n:
            c = s[i]
            if c.isspace():
                i += 1
                continue

            if c == '*':
                if i + 1 < n and s[i+1] == '*':
                    tokens.append(('OP', '**'))
                    i += 2
                else:
                    tokens.append(('OP', '*'))
                    i += 1
            elif c in '+-()/':
                tokens.append(('OP', c))
                i += 1
            elif c.isdigit() or c == '.':
                j = i
                if c == '.':
                    j += 1
                    while j < n and s[j].isdigit():
                        j += 1
                else:
                    while j < n and s[j].isdigit():
                        j += 1
                    if j < n and s[j] == '.':
                        j += 1
                        while j < n and s[j].isdigit():
                            j += 1

                if j > i:
                    tokens.append(('NUM', s[i:j]))
                i = j
            else:
                # Skip unknown characters or raise error
                i += 1
        return tokens

    class Parser:
        def __init__(self, tokens):
            self.tokens = tokens
            self.pos = 0

        def peek(self):
            if self.pos < len(self.tokens):
                return self.tokens[self.pos]
            return None

        def advance(self):
            token = self.tokens[self.pos]
            self.pos += 1
            return token

        def expect(self, type_, value=None):
            token = self.peek()
            if token is None or token[0] != type_ or (value is not None and token[1] != value):
                raise SyntaxError(f"Expected {type_} {value}, got {token}")
            return self.advance()

        def parse_expr(self):
            # expr : term (('+' | '-') term)*
            node = self.parse_term()
            while True:
                token = self.peek()
                if token and token[0] == 'OP' and token[1] in ('+', '-'):
                    op = self.advance()[1]
                    right = self.parse_term()
                    if op == '+':
                        node = node + right
                    else:
                        node = node - right
                else:
                    break
            return node

        def parse_term(self):
            # term : factor (('*' | '/') factor)*
            node = self.parse_factor()
            while True:
                token = self.peek()
                if token and token[0] == 'OP' and token[1] in ('*', '/'):
                    op = self.advance()[1]
                    right = self.parse_factor()
                    if op == '*':
                        node = node * right
                    else:
                        node = node / right
                else:
                    break
            return node

        def parse_factor(self):
            # factor : ('+' | '-') factor | power
            token = self.peek()
            if token and token[0] == 'OP' and token[1] in ('+', '-'):
                op = self.advance()[1]
                val = self.parse_factor()
                if op == '-':
                    return -val
                else:
                    return val
            return self.parse_power()

        def parse_power(self):
            # power : atom ('**' factor)?
            # Note: Right associative. 
            # If we see **, we parse the exponent as a factor (which can be another power).
            base = self.parse_atom()
            token = self.peek()
            if token and token[0] == 'OP' and token[1] == '**':
                self.advance()
                exp = self.parse_factor() # Exponent can be unary negated
                return base ** exp
            return base

        def parse_atom(self):
            # atom : NUMBER | '(' expr ')'
            token = self.peek()
            if token is None:
                raise SyntaxError("Unexpected end of expression")

            if token[0] == 'NUM':
                self.advance()
                return float(token[1])
            elif token[0] == 'OP' and token[1] == '(':
                self.advance()
                val = self.parse_expr()
                self.expect('OP', ')')
                return val
            else:
                raise SyntaxError(f"Unexpected token {token}")

    tokens = tokenize(expr)
    parser = Parser(tokens)
    result = parser.parse_expr()

    # Check if all tokens consumed
    if parser.pos < len(tokens):
        raise SyntaxError(f"Unexpected token {tokens[parser.pos]}")

    return result
