def parse_json(text: str) -> object:
    """Parse a JSON document into Python objects."""
    parser = _JSONParser(text)
    result = parser.parse()
    if parser.pos != len(parser.text):
        raise ValueError("Trailing characters after JSON value")
    return result


class _JSONParser:
    def __init__(self, text: str):
        self.text = text
        self.pos = 0

    def parse(self) -> object:
        self._skip_whitespace()
        if self.pos >= len(self.text):
            raise ValueError("Empty input")
        char = self.text[self.pos]
        if char == '{':
            return self.parse_object()
        elif char == '[':
            return self.parse_array()
        elif char == '"':
            return self.parse_string()
        elif char == 't':
            return self.parse_true()
        elif char == 'f':
            return self.parse_false()
        elif char == 'n':
            return self.parse_null()
        elif char == '-' or char.isdigit():
            return self.parse_number()
        else:
            raise ValueError(f"Unexpected character: {char!r}")

    def _skip_whitespace(self):
        while self.pos < len(self.text) and self.text[self.pos] in ' \t\n\r':
            self.pos += 1

    def _peek(self) -> str:
        if self.pos >= len(self.text):
            raise ValueError("Unexpected end of input")
        return self.text[self.pos]

    def _advance(self) -> str:
        if self.pos >= len(self.text):
            raise ValueError("Unexpected end of input")
        ch = self.text[self.pos]
        self.pos += 1
        return ch

    def _expect(self, expected: str):
        ch = self._advance()
        if ch != expected:
            raise ValueError(f"Expected {expected!r}, got {ch!r}")

    def parse_object(self) -> dict:
        self._expect('{')
        obj = {}
        self._skip_whitespace()
        if self._peek() == '}':
            self._advance()
            return obj
        while True:
            self._skip_whitespace()
            # Parse key
            if self._peek() != '"':
                raise ValueError(f"Expected string key, got {self._peek()!r}")
            key = self.parse_string()
            self._skip_whitespace()
            self._expect(':')
            self._skip_whitespace()
            # Parse value
            value = self.parse()
            obj[key] = value
            self._skip_whitespace()
            ch = self._peek()
            if ch == '}':
                self._advance()
                return obj
            elif ch == ',':
                self._advance()
                # Check for trailing comma
                self._skip_whitespace()
                if self._peek() == '}':
                    raise ValueError("Trailing comma in object")
            else:
                raise ValueError(f"Expected ',' or '}}', got {ch!r}")

    def parse_array(self) -> list:
        self._expect('[')
        arr = []
        self._skip_whitespace()
        if self._peek() == ']':
            self._advance()
            return arr
        while True:
            self._skip_whitespace()
            value = self.parse()
            arr.append(value)
            self._skip_whitespace()
            ch = self._peek()
            if ch == ']':
                self._advance()
                return arr
            elif ch == ',':
                self._advance()
                # Check for trailing comma
                self._skip_whitespace()
                if self._peek() == ']':
                    raise ValueError("Trailing comma in array")
            else:
                raise ValueError(f"Expected ',' or ']', got {ch!r}")

    def parse_string(self) -> str:
        self._expect('"')
        chars = []
        while True:
            if self.pos >= len(self.text):
                raise ValueError("Unterminated string")
            ch = self._advance()
            if ch == '"':
                return ''.join(chars)
            elif ch == '\\':
                if self.pos >= len(self.text):
                    raise ValueError("Unterminated escape sequence")
                esc = self._advance()
                if esc == '"':
                    chars.append('"')
                elif esc == '\\':
                    chars.append('\\')
                elif esc == '/':
                    chars.append('/')
                elif esc == 'b':
                    chars.append('\b')
                elif esc == 'f':
                    chars.append('\f')
                elif esc == 'n':
                    chars.append('\n')
                elif esc == 'r':
                    chars.append('\r')
                elif esc == 't':
                    chars.append('\t')
                elif esc == 'u':
                    # Parse 4 hex digits
                    hex_str = ''
                    for _ in range(4):
                        if self.pos >= len(self.text):
                            raise ValueError("Incomplete unicode escape")
                        h = self._advance()
                        if h not in '0123456789abcdefABCDEF':
                            raise ValueError(f"Invalid hex digit in unicode escape: {h!r}")
                        hex_str += h
                    code_point = int(hex_str, 16)
                    chars.append(chr(code_point))
                else:
                    raise ValueError(f"Invalid escape character: {esc!r}")
            elif ord(ch) < 0x20:
                raise ValueError(f"Invalid control character in string: {ord(ch)!r}")
            else:
                chars.append(ch)

    def parse_number(self) -> object:
        start = self.pos
        # Optional minus
        if self._peek() == '-':
            self._advance()

        # Integer part
        if self.pos >= len(self.text):
            raise ValueError("Unexpected end of input in number")

        if self._peek() == '0':
            self._advance()
            # After leading zero, must not have more digits (no leading zeros like 01)
            if self.pos < len(self.text) and self.text[self.pos].isdigit():
                raise ValueError("Leading zeros not allowed")
        elif self._peek().isdigit():
            while self.pos < len(self.text) and self.text[self.pos].isdigit():
                self._advance()
        else:
            raise ValueError("Invalid number")

        is_float = False

        # Fractional part
        if self.pos < len(self.text) and self.text[self.pos] == '.':
            is_float = True
            self._advance()
            # Must have at least one digit after decimal point
            if self.pos >= len(self.text) or not self.text[self.pos].isdigit():
                raise ValueError("Invalid number: no digits after decimal point")
            while self.pos < len(self.text) and self.text[self.pos].isdigit():
                self._advance()

        # Exponent part
        if self.pos < len(self.text) and self.text[self.pos] in 'eE':
            is_float = True
            self._advance()
            if self.pos < len(self.text) and self.text[self.pos] in '+-':
                self._advance()
            if self.pos >= len(self.text) or not self.text[self.pos].isdigit():
                raise ValueError("Invalid number: no digits in exponent")
            while self.pos < len(self.text) and self.text[self.pos].isdigit():
                self._advance()

        num_str = self.text[start:self.pos]
        if is_float:
            return float(num_str)
        else:
            return int(num_str)

    def parse_true(self) -> bool:
        for expected in 'true':
            if self.pos >= len(self.text) or self.text[self.pos] != expected:
                raise ValueError("Invalid value")
            self._advance()
        return True

    def parse_false(self) -> bool:
        for expected in 'false':
            if self.pos >= len(self.text) or self.text[self.pos] != expected:
                raise ValueError("Invalid value")
            self._advance()
        return False

    def parse_null(self) -> None:
        for expected in 'null':
            if self.pos >= len(self.text) or self.text[self.pos] != expected:
                raise ValueError("Invalid value")
            self._advance()
        return None
