def kth_smallest_distance(nums: list[int], k: int) -> int:
    nums.sort()
    low = 0
    high = nums[-1] - nums[0]

    while low < high:
        mid = (low + high) >> 1
        count = 0
        left = 0
        for right, val_r in enumerate(nums):
            while val_r - nums[left] > mid:
                left += 1
            count += right - left

        if count >= k:
            high = mid
        else:
            low = mid + 1

    return low
