def eval_bool(expr: str, env: dict[str, bool]) -> bool:
    tokens = []
    i = 0
    n = len(expr)
    while i < n:
        c = expr[i]
        if c.isspace():
            i += 1
        elif c == '(':
            tokens.append('(')
            i += 1
        elif c == ')':
            tokens.append(')')
            i += 1
        elif c.isalpha() or c == '_':
            j = i + 1
            while j < n and (expr[j].isalnum() or expr[j] == '_'):
                j += 1
            tokens.append(expr[i:j])
            i = j
        else:
            raise ValueError(f"Invalid character '{c}'")

    pos = 0
    num_tokens = len(tokens)

    def peek():
        return tokens[pos] if pos < num_tokens else None

    def consume(val=None):
        nonlocal pos
        if pos >= num_tokens:
            raise SyntaxError("Unexpected end of input")
        t = tokens[pos]
        if val is not None and t != val:
            raise SyntaxError(f"Expected '{val}', got '{t}'")
        pos += 1
        return t

    def parse_or():
        left = parse_and()
        while peek() == 'or':
            consume('or')
            right = parse_and()
            left = left or right
        return left

    def parse_and():
        left = parse_not()
        while peek() == 'and':
            consume('and')
            right = parse_not()
            left = left and right
        return left

    def parse_not():
        if peek() == 'not':
            consume('not')
            return not parse_not()
        return parse_primary()

    def parse_primary():
        t = peek()
        if t is None:
            raise SyntaxError("Unexpected end of input")

        if t == '(':
            consume('(')
            val = parse_or()
            if peek() != ')':
                raise SyntaxError("Expected ')'")
            consume(')')
            return val
        elif t == 'true':
            consume('true')
            return True
        elif t == 'false':
            consume('false')
            return False
        elif t == ')':
            raise SyntaxError("Unexpected ')'")
        elif t in ('and', 'or', 'not'):
            raise SyntaxError(f"Unexpected token '{t}'")
        else:
            consume(t)
            if t in env:
                return env[t]
            raise KeyError(t)

    result = parse_or()
    if peek() is not None:
        raise SyntaxError(f"Unexpected token '{peek()}'")
    return result
